svg.script:
const NS = 'http://www.w3.org/2000/svg';
const ticks = document.getElementById('ticks');
for (let i = 0; i < 96; i++) {
  const a = i * Math.PI / 48, long = i % 8 === 0, r1 = long ? 326 : 342, r2 = 364;
  const l = document.createElementNS(NS, 'line');
  l.setAttribute('x1', 512 + Math.sin(a) * r1); l.setAttribute('y1', 640 - Math.cos(a) * r1);
  l.setAttribute('x2', 512 + Math.sin(a) * r2); l.setAttribute('y2', 640 - Math.cos(a) * r2);
  ticks.appendChild(l);
}
const spots = [[112,945,-150],[88,860,-120],[72,780,-100],[100,700,-70],[130,630,-130],[118,540,-95],[110,455,-60],[140,385,-110],[190,320,-70],[240,262,-45],
  [905,950,-30],[950,860,-60],[968,775,-80],[925,690,-110],[890,640,-50],[905,555,-85],[918,460,-120],[880,400,-70],[835,335,-100],[795,290,-130]];
const fills = ['#4F6B45', '#5E7A4E', '#7C8A4E', '#C9A85C', '#6F8A55'];
const leaves = document.getElementById('leaves'), ink = document.getElementById('leafInk');
spots.forEach(([x, y, rot], i) => {
  const s = 0.75 + (i % 3) * 0.17, tf = `translate(${x} ${y}) rotate(${rot}) scale(${s})`;
  for (const [parent, attrs] of [[leaves, { fill: fills[i % fills.length], opacity: .9 }], [ink, {}]]) {
    const u = document.createElementNS(NS, 'use'); u.setAttribute('href', '#leaf'); u.setAttribute('transform', tf);
    for (const k in attrs) u.setAttribute(k, attrs[k]); parent.appendChild(u);
  }
  const v = document.createElementNS(NS, 'path'); v.setAttribute('d', 'M4,0 C28,-3 50,-2 70,0'); v.setAttribute('transform', tf); v.setAttribute('stroke-width', 1.3); ink.appendChild(v);
});
